let products=[]; let productPage=1; const productPageSize=24;

let leads=[]; let leadStatus='',leadDuplicateOnly=false;

let roles=[],users=[];let usersBackedBySupabase=false;
let orders=[];
const money=n=>new Intl.NumberFormat('mn-MN').format(n)+'₮';
const slug=s=>({'Шинэ':'new','Бэлтгэж буй':'preparing','Замд':'moving','Хүргэгдсэн':'delivered'}[s]||'new');
const initials=n=>n.split(' ').map(x=>x[0]).join('').slice(-2);
const normalizePhone=value=>String(value||'').replace(/\D/g,'');const todayKey=()=>new Date().toISOString().slice(0,10);const duplicateOrderPhones=()=>{const counts={};orders.filter(order=>(order.dateKey||todayKey())===todayKey()).forEach(order=>{const phone=normalizePhone(order.phone);counts[phone]=(counts[phone]||0)+1});return new Set(Object.keys(counts).filter(phone=>phone&&counts[phone]>1))};const isDuplicatePhone=phone=>duplicateOrderPhones().has(normalizePhone(phone));

const row=(o,full=false)=>{const duplicate=isDuplicatePhone(o.phone);return `<tr class="${duplicate?'duplicate-row':''}">${full?'<td><input type="checkbox" aria-label="Сонгох"></td>':''}<td class="order-id">${o.id}</td><td><div class="customer-cell"><div class="avatar">${initials(o.customer)}</div><div><strong>${o.customer}</strong><small>${o.phone}${duplicate?' <b class="duplicate-badge">Давхар</b>':''}</small></div></div></td>${full?`<td>${o.address}</td>`:`<td>${o.product}</td>`}<td><strong>${money(o.amount)}</strong></td><td><span class="status ${slug(o.status)}">${o.status}</span></td><td>${o.date}</td><td><button class="more-btn" aria-label="Дэлгэрэнгүй"><i data-lucide="ellipsis"></i></button></td></tr>`};
function icons(){if(window.lucide)window.lucide.createIcons()}function showToast(message,type='success'){const toast=document.querySelector('#toast');toast.querySelector('strong').textContent=type==='error'?'Алдаа':'Амжилттай';document.querySelector('#toast-message').textContent=message;toast.classList.toggle('error',type==='error');toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),4200)}
function renderOrders(list=orders){document.querySelector('#recent-orders').innerHTML=list.slice(0,5).map(o=>row(o)).join('');document.querySelector('#orders-table').innerHTML=list.map(o=>row(o,true)).join('');document.querySelector('#all-count').textContent=orders.length;document.querySelector('#order-badge').textContent=orders.length;document.querySelector('#result-count').textContent=`${list.length} үр дүн`;icons()}
function filteredProducts(){const q=document.querySelector('#product-search').value.trim().toLowerCase(),category=document.querySelector('#category-filter').value;return products.filter(p=>(!category||p.category===category)&&(!q||`${p.name} ${p.sku}`.toLowerCase().includes(q)))}
function renderProducts(){const filtered=filteredProducts(),pages=Math.max(1,Math.ceil(filtered.length/productPageSize));productPage=Math.min(productPage,pages);const shown=filtered.slice((productPage-1)*productPageSize,productPage*productPageSize);document.querySelector('#product-grid').innerHTML=shown.map(p=>`<article class="product-card"><button class="product-edit" data-edit-product="${p.id}" aria-label="Бараа засах"><i data-lucide="pencil"></i></button><div class="product-visual"><i data-lucide="package"></i></div><div class="product-body"><h3 title="${p.name}">${p.name}</h3><p>${p.sku||'Кодгүй'}</p><div class="product-meta">${p.category}</div><div class="product-price"><strong>${money(p.price)}</strong><span>${p.stock} үлдэгдэл</span></div></div></article>`).join('')||'<div class="empty-products">Илэрц олдсонгүй.</div>';document.querySelector('#catalog-count').textContent=`${filtered.length.toLocaleString()} бараа`;document.querySelector('#product-page').textContent=`${productPage} / ${pages} хуудас`;document.querySelector('#product-prev').disabled=productPage===1;document.querySelector('#product-next').disabled=productPage===pages;document.querySelectorAll('[data-edit-product]').forEach(b=>b.onclick=()=>openProductModal(b.dataset.editProduct));const low=[...products].sort((a,b)=>a.stock-b.stock).slice(0,12);document.querySelector('#inventory-list').innerHTML=low.map(p=>`<div class="inventory-item"><span class="inventory-icon"><i data-lucide="package"></i></span><div><strong>${p.name}</strong><small>${p.sku||'Кодгүй'} · ${p.category}</small></div><div class="stock-track ${p.stock<10?'low':''}"><span style="width:${Math.min(100,p.stock)}%"></span></div><b>${p.stock} ш</b></div>`).join('');document.querySelector('#product-count').textContent=products.length.toLocaleString();document.querySelector('#out-count').textContent=products.filter(p=>p.stock<=0).length.toLocaleString();document.querySelector('#stock-value').textContent=money(products.reduce((sum,p)=>sum+p.stock*p.cost,0));icons()}
function renderDelivery(){document.querySelector('#courier-list').textContent='Supabase мэдээллийг хүлээж байна.';document.querySelector('#delivery-table').innerHTML=''}
function leadClass(s){return {'Шинэ':'new','Утас аваагүй':'preparing','Дахин холбогдох':'moving','Эргээд залгах':'moving','Захиалга болсон':'delivered'}[s]||'new'}
function relativeCallTime(value){if(!value)return 'Залгалт хийгдээгүй';const minutes=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/60000));if(minutes<1)return 'Дөнгөж сая';if(minutes<60)return `${minutes} минутын өмнө`;const hours=Math.floor(minutes/60);if(hours<24)return `${hours} цагийн өмнө`;return `${Math.floor(hours/24)} өдрийн өмнө`}
function recordLeadCall(lead,status){const at=new Date().toISOString();lead.attempts=(lead.attempts||0)+1;lead.lastCall=at;lead.callHistory=lead.callHistory||[];lead.callHistory.unshift({operator:lead.operator||'Хуваарилаагүй',status,at})}
function leadCallHistory(lead){const history=lead.callHistory||[];if(history.length)return history.slice(0,6).map(call=>`<div><strong>${call.operator}</strong><span>${call.status}</span><time>${relativeCallTime(call.at)}</time></div>`).join('');if(lead.lastCall)return `<div><strong>${lead.operator||'Хуваарилаагүй'}</strong><span>Залгалт</span><time>${relativeCallTime(lead.lastCall)}</time></div>`;return '<small>Залгалтын түүх байхгүй.</small>'}
function renderLeads(){const q=document.querySelector('#lead-search').value.toLowerCase(),page=document.querySelector('#lead-page-filter').value,statusFilter=document.querySelector('#lead-status-filter').value,selectedStatus=leadStatus||statusFilter,archived=['Авахаа больсон','Цуцалсан','Бусад'];const active=leads.filter(l=>!archived.includes(l.status)),source=selectedStatus?leads:active,followUpStatuses=['Утас аваагүй','Дахин холбогдох','Холбогдох боломжгүй','Эргээд залгах'];const duplicatePhones=duplicateOrderPhones(),list=source.filter(l=>(!selectedStatus||l.status===selectedStatus)&&(!page||l.page===page)&&(!leadDuplicateOnly||duplicatePhones.has(normalizePhone(l.phone)))&&Object.values(l).join(' ').toLowerCase().includes(q));document.querySelector('#leads-table').innerHTML=list.map((l,i)=>`<tr class="${duplicatePhones.has(normalizePhone(l.phone))?'duplicate-row':''}"><td><strong>${i+1}</strong><small class="lead-time"> · ${l.created}</small></td><td><div class="lead-contact"><strong>${l.customer||'Нэргүй'} · ${l.phone}${duplicatePhones.has(normalizePhone(l.phone))?' <b class="duplicate-badge">Давхар</b>':''}</strong><small>${l.comment}</small></div></td><td><span class="page-chip">${l.page}</span></td><td><strong>${l.product}</strong></td><td><div class="operator-call"><strong>${l.operator}</strong><small>${l.attempts||0} удаа залгасан</small><time>${relativeCallTime(l.lastCall)}</time></div></td><td><button class="status-display ${leadClass(l.status)}" data-open-lead-status="${l.id}">${l.status}</button></td><td><div class="lead-actions"><button class="call" data-lead-action="call" data-id="${l.id}" title="Залгалт бүртгэх"><i data-lucide="phone"></i></button><button class="convert" data-lead-action="convert" data-id="${l.id}" title="Захиалга болгох"><i data-lucide="shopping-bag"></i></button></div></td></tr>`).join('')||'<tr><td colspan="7">Илэрц олдсонгүй.</td></tr>';document.querySelector('#lead-total').textContent=leads.length;document.querySelector('#lead-new').textContent=active.filter(l=>l.status==='Шинэ'||followUpStatuses.includes(l.status)).length;document.querySelector('#lead-converted').textContent=leads.filter(l=>l.status==='Захиалга болсон').length;document.querySelector('#lead-failed').textContent=active.filter(l=>followUpStatuses.includes(l.status)).length;document.querySelector('#lead-dropped').textContent=leads.filter(l=>l.status==='Авахаа больсон').length;document.querySelector('#lead-cancelled').textContent=leads.filter(l=>l.status==='Цуцалсан').length;document.querySelector('#lead-badge').textContent=active.filter(l=>l.status==='Шинэ'||followUpStatuses.includes(l.status)).length;document.querySelector('#lead-count').textContent=`${list.length} дугаар`;document.querySelector('#duplicate-count').textContent=duplicatePhones.size;const operatorStats=Object.values(leads.reduce((result,l)=>{const name=l.operator||'Хуваарилаагүй';result[name]||={name,total:0,attempts:0,converted:0,followUp:0};result[name].total++;result[name].attempts+=Number(l.attempts||0);if(l.status==='Захиалга болсон')result[name].converted++;if(followUpStatuses.includes(l.status))result[name].followUp++;return result},{}));document.querySelector('#operator-grid').innerHTML=operatorStats.map(o=>`<article class="operator-card"><div class="operator-card-head"><span class="avatar small teal">${initials(o.name)}</span><div><strong>${o.name}</strong><small>${o.total} дугаар хуваарилсан</small></div><b>${o.total?Math.round(o.converted/o.total*100):0}%</b></div><div class="operator-card-metrics"><span><small>Залгалт</small><strong>${o.attempts}</strong></span><span><small>Захиалга</small><strong>${o.converted}</strong></span><span><small>Дахин залгах</small><strong>${o.followUp}</strong></span></div></article>`).join('')||'<p class="empty-products">Операторын мэдээлэл алга.</p>';document.querySelectorAll('[data-lead-action]').forEach(b=>b.onclick=()=>updateLead(Number(b.dataset.id),b.dataset.leadAction));document.querySelectorAll('[data-open-lead-status]').forEach(b=>b.onclick=()=>openLeadStatusModal(Number(b.dataset.openLeadStatus)));icons()}
function updateLead(){showToast('Мэдээллийн холболтыг хүлээнэ үү.','error')}
const leadStatusModal=document.querySelector('#lead-status-modal'),leadStatusForm=document.querySelector('#lead-status-form');function openLeadStatusModal(id){const lead=leads.find(l=>l.id===id);if(!lead)return;leadStatusForm.elements.leadId.value=id;leadStatusForm.elements.status.value=lead.status;document.querySelector('#lead-status-title').textContent=lead.customer||'Нэргүй';document.querySelector('#lead-status-summary').innerHTML=`<strong>${lead.phone}</strong><span>${lead.page}</span><span>${lead.product}</span><small>${lead.attempts||0} удаа залгасан · ${relativeCallTime(lead.lastCall)}</small><div class="call-history">${leadCallHistory(lead)}</div>`;leadStatusModal.classList.add('open');leadStatusModal.setAttribute('aria-hidden','false')}function closeLeadStatusModal(){leadStatusModal.classList.remove('open');leadStatusModal.setAttribute('aria-hidden','true')}document.querySelector('#lead-status-close').onclick=closeLeadStatusModal;document.querySelector('#lead-status-cancel').onclick=closeLeadStatusModal;leadStatusModal.onclick=e=>{if(e.target===leadStatusModal)closeLeadStatusModal()};leadStatusForm.onsubmit=e=>{e.preventDefault();updateLead(Number(leadStatusForm.elements.leadId.value),'status',leadStatusForm.elements.status.value);closeLeadStatusModal()};
function renderMenus(){const reports=[['chart-column-big','Борлуулалтын тайлан','Салбар, бараа, сувгаар'],['truck','Хүргэлтийн тайлан','Гүйцэтгэл, хугацаа, ажилтнаар'],['package-search','Агуулахын тайлан','Үлдэгдэл, хөдөлгөөн, тооллого'],['users','Харилцагчийн тайлан','Давтамж, сегмент, өсөлт']];document.querySelector('#report-grid').innerHTML=reports.map(x=>`<button><span><i data-lucide="${x[0]}"></i></span><div><strong>${x[1]}</strong><small>${x[2]}</small></div><i data-lucide="arrow-right"></i></button>`).join('')}
function refreshRoleOptions(){const options=roles.map(r=>`<option value="${r.id}">${r.name}</option>`).join('');document.querySelector('#new-user-role').innerHTML=options;document.querySelector('#user-role-filter').innerHTML='<option value="">Бүх хандах эрх</option>'+roles.map(r=>`<option value="${r.name}">${r.name}</option>`).join('')}
let userManagementLoadRevision=0;
async function loadUserManagementData(){
  const context=window.nexerpAuth,client=context?.client;
  const actorId=context?.profile?.id,organizationId=context?.profile?.organizationId;
  if(!client||!actorId||!organizationId)return false;
  const revision=++userManagementLoadRevision;
  const current=()=>revision===userManagementLoadRevision&&window.nexerpAuth===context&&
    context.client===client&&context.profile?.id===actorId&&context.profile?.organizationId===organizationId;
  try{
    const[{data:profiles,error:profileError},{data:dbRoles,error:roleError},{data:assignments,error:assignmentError}]=await Promise.all([
      client.from('profiles').select('id,email,first_name,last_name,phone,department,position,status,employment_start_date').order('created_at',{ascending:false}),
      client.from('roles').select('id,name,description,is_system,role_permissions(permission_code)').order('name'),
      client.from('user_roles').select('user_id,role_id,roles(name)')
    ]);
    if(!current())return false;
    if(profileError||roleError||assignmentError||!Array.isArray(profiles)||!Array.isArray(dbRoles)||!Array.isArray(assignments)){
      showToast('Хэрэглэгчийн жагсаалтыг шинэчилж чадсангүй. Холболт болон эрхээ шалгана уу.','error');return false;
    }
    const assignmentByUser=new Map(assignments.map(item=>[item.user_id,item]));
    roles=dbRoles.map(role=>({id:role.id,name:role.name,description:role.description,permissions:(role.role_permissions||[]).map(item=>item.permission_code),locked:role.is_system}));
    users=profiles.map(profile=>({id:profile.id,lastName:profile.last_name||'',firstName:profile.first_name||profile.email,email:profile.email,phone:profile.phone||'',department:profile.department||'',position:profile.position||'',role:assignmentByUser.get(profile.id)?.roles?.name||'Эрхгүй',roleId:assignmentByUser.get(profile.id)?.role_id,startDate:profile.employment_start_date||'',active:profile.status==='active'}));
    usersBackedBySupabase=true;refreshRoleOptions();renderSettings();return true;
  }catch{
    if(current())showToast('Хэрэглэгчийн жагсаалтыг шинэчилж чадсангүй. Холболт болон эрхээ шалгана уу.','error');
    return false;
  }
}
async function toggleSupabaseUser(user){if(user.role==='Admin'&&user.id===window.nexerpAuth?.profile?.id)return;const nextStatus=user.active?'disabled':'active';const{error}=await window.nexerpAuth.client.from('profiles').update({status:nextStatus}).eq('id',user.id);if(error){showToast(error.message||'Хэрэглэгчийн төлөв шинэчилж чадсангүй.','error');return}await loadUserManagementData()}
function renderSettings(){const q=document.querySelector('#user-search').value.toLowerCase(),role=document.querySelector('#user-role-filter').value,list=users.filter(u=>(!role||u.role===role)&&Object.values(u).join(' ').toLowerCase().includes(q)),canManage=window.nexerpAuth?.can?.('users.manage');document.querySelector('#users-table').innerHTML=list.map(u=>{const own=u.id===window.nexerpAuth?.profile?.id,roleControl=canManage&&!own?`<select class="role-assignment" data-assign-role="${u.id}" aria-label="${u.email} хэрэглэгчийн эрх">${roles.map(r=>`<option value="${r.id}" ${r.id===u.roleId?'selected':''}>${r.name}</option>`).join('')}</select>`:`<span class="role-pill ${u.role==='Admin'?'owner':''}">${u.role}</span>`;return `<tr><td><div class="user-name"><div class="avatar">${initials(`${u.lastName||''} ${u.firstName||''}`)}</div><div><strong>${u.lastName?`${u.lastName[0]}. `:''}${u.firstName||u.email}</strong><small>${u.email}</small></div></div></td><td>${u.phone||'-'}</td><td>${u.department||'-'}<br><small>${u.position||'-'}</small></td><td>${roleControl}</td><td><span class="user-status ${u.active?'active':'inactive'}">${u.active?'Идэвхтэй':'Идэвхгүй'}</span></td><td><div class="user-actions"><button data-toggle-user="${u.id}" title="Төлөв солих"><i data-lucide="power"></i></button></div></td></tr>`}).join('');document.querySelector('#user-count').textContent=`${list.length} хэрэглэгч`;document.querySelectorAll('[data-assign-role]').forEach(select=>select.onchange=async()=>{const user=users.find(item=>String(item.id)===select.dataset.assignRole),previous=user?.roleId;select.disabled=true;try{const{error}=await window.nexerpAuth.client.rpc('assign_user_role',{target_user_id:select.dataset.assignRole,target_role_id:select.value});if(error)throw error;await loadUserManagementData();showToast('Хэрэглэгчийн хандах эрх шинэчлэгдлээ.')}catch(error){select.value=previous||'';select.disabled=false;showToast(error.message||'Хандах эрх оноож чадсангүй.','error')}});document.querySelectorAll('[data-toggle-user]').forEach(b=>b.onclick=async()=>{const u=users.find(x=>String(x.id)===b.dataset.toggleUser);if(!u)return;if(usersBackedBySupabase){await toggleSupabaseUser(u);return}if(u.role!=='Owner')u.active=!u.active;renderSettings()});document.querySelector('#role-grid').innerHTML=roles.map(r=>`<article class="role-card"><div class="role-card-head"><span class="role-card-icon"><i data-lucide="${r.name==='Admin'?'crown':'shield-check'}"></i></span>${canManage&&!r.locked?`<button class="icon-btn" data-edit-role="${r.id}" title="Хандах эрх засах"><i data-lucide="pencil"></i></button>`:`<span class="role-pill ${r.name==='Admin'?'owner':''}">Системийн</span>`}</div><h3>${r.name}</h3><p>${r.description}</p><div class="role-card-footer"><span>${r.permissions.length} зөвшөөрөл</span><strong>${users.filter(u=>u.role===r.name).length} хэрэглэгч</strong></div></article>`).join('');document.querySelectorAll('[data-edit-role]').forEach(button=>button.onclick=()=>openRoleModal(roles.find(role=>role.id===button.dataset.editRole)));icons()}
function installAIModules(){const systemLabel=[...document.querySelectorAll('.main-nav .nav-label')].find(label=>label.textContent.trim()==='СИСТЕМ'),settingsView=document.querySelector('#view-settings');if(systemLabel&&!document.querySelector('[data-view="ai-assistant"]'))systemLabel.insertAdjacentHTML('beforebegin','<p class="nav-label">AI &amp; AUTOMATION</p><button class="nav-item" data-view="ai-assistant"><i data-lucide="sparkles"></i><span>AI туслах</span><b class="nav-beta">BETA</b></button><button class="nav-item" data-view="ai-inbox"><i data-lucide="messages-square"></i><span>Facebook Inbox</span><b class="nav-beta">AI</b></button>');if(settingsView&&!document.querySelector('#view-ai-assistant'))settingsView.insertAdjacentHTML('beforebegin','<section class="view" id="view-ai-assistant"><div class="page-heading"><div><p class="eyebrow">AI ТУСЛАХ</p><h1>Momo AI</h1><p>ERP мэдээлэлд тулгуурласан ажлын туслах.</p></div><span class="integration-status pending"><i data-lucide="circle-dot"></i> Туршилтын горим</span></div><div class="ai-workspace"><section class="panel ai-chat"><div class="ai-chat-head"><span class="ai-avatar"><i data-lucide="sparkles"></i></span><div><strong>Momo AI</strong><small>Холболт хүлээгдэж байна</small></div></div><div class="ai-chat-body"><div class="ai-message assistant"><p>AI үйлчилгээний холболт бэлэн болмогц эндээс тайлан, захиалга болон барааны мэдээлэлтэй ажиллана.</p></div></div><div class="ai-composer"><input aria-label="AI туслахаас асуух" placeholder="AI үйлчилгээ холбогдоогүй байна" disabled><button class="icon-btn" type="button" disabled aria-label="Илгээх"><i data-lucide="send"></i></button></div></section><aside class="panel ai-side"><div class="panel-head"><div><h3>Шуурхай үйлдэл</h3><p>Бэлэн болмогц идэвхжинэ</p></div></div><button disabled><i data-lucide="chart-no-axes-combined"></i><span>Өдрийн тайлан</span></button><button disabled><i data-lucide="package-search"></i><span>Үлдэгдэл шалгах</span></button><button disabled><i data-lucide="shopping-bag"></i><span>Захиалга дүгнэх</span></button></aside></div></section><section class="view" id="view-ai-inbox"><div class="page-heading"><div><p class="eyebrow">AI BOT</p><h1>Facebook Inbox</h1><p>Page чат болон комментын нэгдсэн урсгал.</p></div><span class="integration-status offline"><i data-lucide="unlink"></i> Meta холбоогүй</span></div><div class="inbox-shell panel"><aside class="inbox-sidebar"><div class="inbox-tabs"><button class="active" type="button"><i data-lucide="message-circle"></i> Чат</button><button type="button"><i data-lucide="message-square-reply"></i> Коммент</button></div><div class="inbox-search"><i data-lucide="search"></i><input aria-label="Inbox хайлт" placeholder="Нэр, мессежээр хайх" disabled></div><div class="inbox-empty-list"><i data-lucide="facebook"></i><span>Page холбоогүй</span></div></aside><section class="inbox-content"><div class="inbox-empty"><span><i data-lucide="messages-square"></i></span><h2>Facebook page холбоно уу</h2><p>Meta webhook болон Page access token сервер талд тохирсны дараа чат, коммент энд орж ирнэ.</p><button class="btn primary" type="button" disabled><i data-lucide="link-2"></i> Page холбох</button></div></section></div></section>')}
